fn build_bag_from_tape(reader: &mut TapeReader<'_>, depth: u32) -> Bag {
    if depth == 0 {
        let result = AnyTerm::WrapBag(Bag::BagLit(mettail_runtime::HashBag::new()));
        return result.unwrap_bag();
    }

    let choice = (reader.next_byte() as usize) % 4;
    let child_depth = depth - 1;
    match choice {
        0 => AnyTerm::WrapBag(Bag::BagLit(mettail_runtime::HashBag::new())).unwrap_bag(),
        1 => {
            let f0 = std::sync::Arc::new(build_bag_from_tape(reader, child_depth));
            let f1 = std::sync::Arc::new(build_bag_from_tape(reader, child_depth));
            Bag::UnionBag(f0, f1)
        },
        2 => {
            let f0 = std::sync::Arc::new(build_bag_from_tape(reader, child_depth));
            let f1 = std::sync::Arc::new(build_proc_from_tape(reader, child_depth));
            Bag::RemoveBag(f0, f1)
        },
        _ => {
            let f0 = std::sync::Arc::new(build_bag_from_tape(reader, child_depth));
            let f1 = std::sync::Arc::new(build_bag_from_tape(reader, child_depth));
            Bag::DiffBag(f0, f1)
        },
    }
}

/// Build a `Map` term from an instruction tape.
///
/// Consumes bytes from the tape to choose constructors.
/// At depth 0, only leaf constructors (nullary, literal, var) are chosen.
/// At depth > 0, recursive constructors are also available.
#[allow(dead_code, unused_variables, clippy::let_and_return)]
fn build_map_from_tape(reader: &mut TapeReader<'_>, depth: u32) -> Map {
    if depth == 0 {
        let result = AnyTerm::WrapMap(Map::MapLit(mettail_runtime::HashMapLit::new()));
        return result.unwrap_map();
    }

    let choice = (reader.next_byte() as usize) % 4;
    let child_depth = depth - 1;
    match choice {
        0 => AnyTerm::WrapMap(Map::MapLit(mettail_runtime::HashMapLit::new())).unwrap_map(),
        1 => {
            let f0 = std::sync::Arc::new(build_map_from_tape(reader, child_depth));
            let f1 = std::sync::Arc::new(build_proc_from_tape(reader, child_depth));
            let f2 = std::sync::Arc::new(build_proc_from_tape(reader, child_depth));
            Map::PutMap(f0, f1, f2)
        },
        2 => {
            let f0 = std::sync::Arc::new(build_map_from_tape(reader, child_depth));
            let f1 = std::sync::Arc::new(build_proc_from_tape(reader, child_depth));
            Map::DeleteMap(f0, f1)
        },
        _ => {
            let f0 = std::sync::Arc::new(build_map_from_tape(reader, child_depth));
            let f1 = std::sync::Arc::new(build_map_from_tape(reader, child_depth));
            Map::MergeMap(f0, f1)
        },
    }
}

/// Generate an arbitrary `Proc` term with bounded depth.
///
/// Uses a flat `Vec<u8>` tape interpreted by `build_proc_from_tape`.
/// Proptest shrinking produces shorter tapes = simpler terms.
#[allow(dead_code)]
fn arb_proc(max_depth: u32) -> BoxedStrategy<Proc> {
    // Tape size scales with depth: deeper terms need more bytes
    let max_tape = (10 * (max_depth as usize + 1)).max(20);
    proptest::collection::vec(any::<u8>(), 1..max_tape)
        .prop_map(move |tape| {
            let mut reader = TapeReader::new(&tape);
            build_proc_from_tape(&mut reader, max_depth)
        })
        .boxed()
}

